'use strict';
const table=(head,rows)=>`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const beanX=[15,20,30,40,50,60,70,80,90,95],beanY=[0,.1,.5,1.2,2,2.5,2.1,1.2,.1,0];
function chart(xs,series,ymax,ylabel,xlabel,marker=null){const X=x=>70+(x-xs[0])/(xs.at(-1)-xs[0])*570,Y=y=>280-y/ymax*210;return `<svg class="chart" viewBox="0 0 700 380" role="img" aria-label="${ylabel} in Abhängigkeit von ${xlabel}"><rect width="700" height="380" fill="white"/>${(ymax===3?[0,1/6,2/6,3/6,4/6,5/6,1]:[0,.2,.4,.6,.8,1]).map(t=>`<line class="gridline" x1="70" x2="640" y1="${Y(t*ymax)}" y2="${Y(t*ymax)}"/><text x="58" y="${Y(t*ymax)+5}" text-anchor="end">${String(+(t*ymax).toFixed(2)).replace('.',',')}</text>`).join('')}<path class="axis" fill="none" d="M70 60V280H650"/><text x="70" y="25">${ylabel}</text>${xs.map(x=>`<text x="${X(x)}" y="302" text-anchor="middle">${x}</text>`).join('')}<text x="355" y="329" text-anchor="middle">${xlabel}</text>${series.map((s,i)=>`<polyline fill="none" stroke="${s.color}" stroke-width="3" ${i?'stroke-dasharray="7 4"':''} points="${s.values.map((y,j)=>`${X(xs[j])},${Y(y)}`).join(' ')}"/>${s.values.map((y,j)=>`<circle cx="${X(xs[j])}" cy="${Y(y)}" r="4" fill="${s.color}"/>`).join('')}<line x1="${75+i*270}" x2="${100+i*270}" y1="355" y2="355" stroke="${s.color}" stroke-width="3" ${i?'stroke-dasharray="7 4"':''}/><text x="${108+i*270}" y="360">${s.label}</text>`).join('')}${marker!==null?`<line x1="${X(marker)}" x2="${X(marker)}" y1="55" y2="280" stroke="#b46b1f" stroke-width="2" stroke-dasharray="4 4"/>`:''}</svg>`}
const beans=()=>`<figure>${chart(beanX,[{label:'Bohnenpflanzen',color:'#087c88',values:beanY}],3,'Zuwachs der Trockenmasse in g','Bodenfeuchtigkeit in %')}<figcaption>Modellversuch aus AB 2. Mittelwerte nach vier Wochen; didaktisch modellierte Daten. Die Linien verbinden die Messpunkte.</figcaption></figure>`;
const beanTable=table(['Bodenfeuchte (%)',...beanX], [['Trockenmassezuwachs (g)',...beanY.map(x=>String(x).replace('.',','))]]);
const pineTable=table(['Bodenfeuchte (%)',15,30,45,60,75,90],[['Waldkiefer allein',3,6,9,10,8,4],['Waldkiefer mit Rotbuche',3,5,3,1,2,4],['Rotbuche allein',0,3,8,10,9,1],['Rotbuche mit Waldkiefer',0,3,8,9,8,1]]);
const siteTable=table(['Merkmal','A: offene Rasenfläche','B: unter Laubbäumen'],[['Licht um 12 Uhr','42.000 Lux','3.500 Lux'],['Licht im Jahresverlauf','Offen; wetter- und jahreszeitabhängig','Vor Laubaustrieb heller, im Sommer schattig'],['Temperatur um 12 Uhr','22 °C','17 °C'],['Boden','Mäßig trocken, stellenweise verdichtet','Mäßig feucht, humusreich, oberflächlich locker'],['Pflege','Alle zwei Wochen kurze Mahd','Keine regelmäßige Mahd, Laub bleibt liegen'],['Nutzung','Pausenfläche; Randstreifen veränderbar','Selten betreten; Bäume bleiben erhalten'],['Nährstoffversorgung','Nicht untersucht','Nicht untersucht']]);
const plants=table(['Pflanze','Ansprüche und Pflege','Blütezeit etwa','Nahrung für Bienen'],[['Gänseblümchen','Hell, frischer Boden; niedrige Rosette verträgt Mahd, Blüten können abgeschnitten werden','Feb.–Nov.','Nektar und Pollen'],['Breitwegerich','Hell bis teilweise beschattet, frischer Boden; tritt- und mahdtolerant','Juni–Okt.','Kein Nektar; Pollen kann gesammelt werden'],['Echter Wurmfarn','Schattig bis halbschattig, frisch bis feucht und humusreich; keine regelmäßige Mahd','Keine Blüten','Weder Nektar noch Pollen; Sporenpflanze'],['Weißklee','Hell, frischer Boden; kriechende Triebe überstehen Mahd, Blütenstände nicht immer','Mai–Sept.','Nektar und Pollen'],['Kleine Braunelle','Sonnig bis halbschattig, frisch bis feucht; Blütentriebe müssen stehen bleiben','Juni–Sept.','Nektar und Pollen'],['Geflecktes Lungenkraut','Halbschattig bis schattig, frisch bis feucht, humus- und nährstoffreich; geringe Trittbelastung','März–Mai','Nektar und Pollen']]);
window.GK={topics:[
  {
    "id": "oekosystem",
    "title": "Ökosystem & Umweltfaktoren",
    "short": "Ökosystem",
    "desc": "Wie Lebensraum, Lebensgemeinschaft und Umweltfaktoren zusammenwirken.",
    "source": "Unterricht zu Ökosystemen und Umweltfaktoren (AB 1)",
    "sections": [
      [
        "Ökosystem, Biotop und Biozönose",
        "<p><b>Ökologie</b> untersucht die Beziehungen von Lebewesen untereinander und zu ihrer Umwelt. Ein <b>Ökosystem</b> umfasst einen Lebensraum, die dort lebende Lebensgemeinschaft und ihre Wechselwirkungen. Entscheidend ist also nicht nur, welche Bestandteile vorkommen, sondern auch, wie sie einander beeinflussen.</p>\n<h3>Die Organisationsebenen unterscheiden</h3>\n<p>Ein einzelnes Lebewesen ist ein <b>Organismus</b>. Die Individuen derselben Art, die zur gleichen Zeit in einem Gebiet leben, bilden eine <b>Population</b>. Die Populationen verschiedener Arten bilden zusammen die <b>Biozönose</b>. Dazu gehören auch unscheinbare Lebewesen wie Pilze und Bakterien.</p>\n<p>Das <b>Biotop</b> ist der räumlich abgrenzbare Lebensraum mit seinen unbelebten Bestandteilen und Bedingungen. Hierzu zählen beispielsweise Boden, Wasser, Temperatur und Lichtverhältnisse. Biotop und Biozönose ergeben erst durch ihr Zusammenwirken das Ökosystem.</p>\n<p><b>Beispiel Wiese:</b> Alle Gänseblümchen einer Wiese gehören zu einer Population. Zusammen mit Gräsern, Regenwürmern und weiteren Arten sind sie Teil der Biozönose. Bodenfeuchte und Lichtverhältnisse gehören zum Biotop.</p>\n<div class=\"note\"><b>Merke:</b> Ein Ökosystem muss weder natürlich entstanden noch von seiner Umgebung abgeschlossen sein. Auch ein angelegter Gartenteich kann ein Ökosystem sein. Seine Abgrenzung hängt von der betrachteten Fragestellung ab.</div>"
      ],
      [
        "Abiotische und biotische Umweltfaktoren",
        "<p>Ein <b>Umweltfaktor</b> ist eine Umweltbedingung oder ein Einfluss, der sich auf Lebewesen auswirkt. Umweltfaktoren beeinflussen etwa Aktivität, Wachstum, Überleben und Fortpflanzung.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Abiotische Faktoren</th><th>Biotische Faktoren</th></tr></thead><tbody><tr><td>Einflüsse der unbelebten Umwelt: Licht, Temperatur, Wasserverfügbarkeit, Salzgehalt oder Sauerstoffgehalt.</td><td>Einflüsse durch Lebewesen: Konkurrenz, Fraß, Parasitismus oder gegenseitige Unterstützung.</td></tr><tr><td>Beispiel: Ein trockener Boden erschwert die Wasserversorgung einer Pflanze.</td><td>Beispiel: Eine Nachbarpflanze entzieht demselben Boden Wasser und verringert dadurch das verfügbare Angebot.</td></tr></tbody></table></div>\n<p><b>Ressource und Beziehung sind nicht dasselbe.</b> Wasser ist ein unbelebter Bestandteil der Umwelt. Konkurrenz um Wasser ist dagegen eine biotische Beziehung, weil sich Lebewesen gegenseitig beeinträchtigen. Ähnlich ist Licht abiotisch, während die Beschattung durch eine Nachbarpflanze einen biotischen Einfluss darstellt.</p>\n<p>Die Faktoren wirken gleichzeitig: Ein heller Standort kann durch starke Erwärmung auch trockener sein. Eine Pflanze erhält dort möglicherweise viel Licht, wird aber durch Wassermangel begrenzt. Deshalb reicht ein einzelner günstiger Faktor nicht aus, um gute Lebensbedingungen vorherzusagen.</p>\n<div class=\"note\"><b>Zum Einordnen:</b> Frage zunächst, welche Bedingung betrachtet wird. Frage dann, ob und wie ein anderes Lebewesen diese Bedingung beeinflusst.</div>"
      ],
      [
        "Wechselwirkungen im Ökosystem erklären",
        "<p>Die unbelebte Umwelt beeinflusst die Lebewesen – und Lebewesen verändern ihre Umwelt. Diese Rückwirkungen machen ein Ökosystem zu einem <b>zusammenhängenden System</b>.</p>\n<h3>Von der Bedingung zur biologischen Wirkung</h3>\n<p>Unter geeigneten Bedingungen ermöglicht mehr Licht eine höhere Fotosyntheseleistung grüner Pflanzen. Dabei können mehr energiereiche Stoffe aufgebaut und mehr Sauerstoff freigesetzt werden. Der verfügbare Sauerstoff beeinflusst wiederum Organismen, die ihn für ihre Zellatmung benötigen. Pflanzen betreiben selbst ebenfalls Zellatmung.</p>\n<p>Auch an Land bestehen solche Verknüpfungen: Die Blätter einer Rotbuche beschatten den Boden. Dadurch verändern sich die Lichtverhältnisse für Bodenpflanzen. Beschattung kann außerdem die Erwärmung und Austrocknung des Bodens verringern. Eine Art verändert somit mehrere Bedingungen für andere Arten.</p>\n<h3>Eine Wirkung ist noch nicht das Gesamtergebnis</h3>\n<p>Eine höhere Sauerstoffproduktion bedeutet nicht zwangsläufig einen höheren gemessenen Sauerstoffgehalt. Gleichzeitig wird Sauerstoff verbraucht und mit der Umgebung ausgetauscht. Das beobachtete Ergebnis entsteht aus dem Zusammenwirken dieser Vorgänge.</p>\n<div class=\"note\"><b>Eine gute Erklärung verbindet:</b> veränderte Bedingung → biologischer Vorgang → mögliche Folge. „Mehr Licht beeinflusst Pflanzen“ nennt nur einen Zusammenhang. „Mehr nutzbares Licht kann die Fotosynthese und damit den Stoffaufbau erhöhen“ erklärt die Wirkung.</div>"
      ]
    ]
  },
  {
    "id": "toleranz",
    "title": "Abiotische Faktoren & Toleranzkurven",
    "short": "Toleranzkurven",
    "desc": "Warum Umweltfaktoren Lebensleistungen begrenzen und wie Toleranzbereiche zu verstehen sind.",
    "source": "Wirkung abiotischer Faktoren und Toleranzbegriffe (AB 2)",
    "sections": [
      [
        "Warum Umweltfaktoren die Lebensleistung verändern",
        "<p>Lebewesen benötigen geeignete Umweltbedingungen, weil ihre Körperfunktionen nur innerhalb bestimmter Grenzen ablaufen können. Eine <b>Lebensleistung</b> ist beispielsweise Wachstum, Aktivität oder Fortpflanzung. Welche Leistung betrachtet wird, muss jeweils benannt werden.</p>\n<h3>Zu wenig und zu viel können begrenzen</h3>\n<p>Wasser ermöglicht Stofftransport und erhält den Druck in Pflanzenzellen, der zur Stabilität der Pflanze beiträgt. Bei Wassermangel können Blätter welken und Wachstumsvorgänge eingeschränkt sein. Ein dauerhaft wassergesättigter Boden kann ebenfalls ungünstig sein: Wasser verdrängt Luft aus den Bodenporen; dadurch wird die Sauerstoffversorgung der Wurzeln erschwert. Die Wurzelzellen benötigen Sauerstoff für eine ausreichende Energiegewinnung durch Zellatmung.</p>\n<p>Temperatur beeinflusst die Geschwindigkeit vieler Stoffwechselvorgänge. Bei einer wechselwarmen Zauneidechse hängen Körpertemperatur und Aktivität stark von Umgebung und Verhalten ab. Kälte kann die Aktivität begrenzen; übermäßige Hitze kann Körperfunktionen schädigen. Mehr Wärme ist daher nicht unbegrenzt besser.</p>\n<div class=\"note\"><b>Grundgedanke:</b> Häufig liegt zwischen ungünstigen niedrigen und ungünstigen hohen Faktorwerten ein günstiger Bereich. Dessen Lage ist abhängig von Art, Lebensstadium, betrachteter Leistung und weiteren Umweltbedingungen.</div>"
      ],
      [
        "Toleranzkurve: Begriffe und Zusammenhänge",
        "<p>Eine <b>Toleranzkurve</b> stellt die Lebensleistung in Abhängigkeit von einem Umweltfaktor dar. Die x-Achse zeigt dessen Stärke, die y-Achse die betrachtete Leistung. Die Form ist ein vereinfachtes Modell; reale Kurven müssen nicht symmetrisch sein.</p>\n<figure><img class=\"knowledge-curve\" src=\"assets/toleranz-grundlagen.svg\" alt=\"Schematische Toleranzkurve: Minimum und Maximum begrenzen den Überlebensbereich. Dazwischen liegen zwei Pessima am Rand, der Fortpflanzungsbereich und das Präferendum um das Optimum.\"><figcaption>Schematische Lehrdarstellung ohne Messwerte oder Artbezug. Auf schmalen Bildschirmen lässt sich das Diagramm seitlich verschieben. Die Angaben zu Überleben und Fortpflanzung sind hier zusätzlich vorausgesetzt; sie folgen nicht allein aus der Kurvenhöhe.</figcaption></figure>\n<div class=\"table-wrap\"><table><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody>\n<tr><td><b>Minimum / Maximum</b></td><td>Untere bzw. obere Grenze des Überlebensbereichs. Beide bezeichnen Faktorwerte, nicht die Höhe der Leistung.</td></tr>\n<tr><td><b>Toleranzbereich</b></td><td>Gesamter Bereich zwischen den Überlebensgrenzen; er umfasst auch die ungünstigen Randbereiche.</td></tr>\n<tr><td><b>Pessimum</b></td><td>Randbereich, in dem Überleben noch möglich ist, erfolgreiche Fortpflanzung jedoch nicht. Die beiden Randbereiche heißen Pessima.</td></tr>\n<tr><td><b>Optimum</b></td><td>Faktorwert mit der höchsten untersuchten Leistung. Ein Wachstumsoptimum ist nicht automatisch das Optimum jeder anderen Leistung.</td></tr>\n<tr><td><b>Präferendum</b></td><td>Besonders günstiger Bereich um das Optimum; ein Bereich, kein einzelner Punkt.</td></tr>\n<tr><td><b>Fortpflanzungsbereich</b></td><td>Bereich, in dem zusätzlich zum Überleben erfolgreiche Fortpflanzung möglich ist. Er umfasst nicht die Pessima.</td></tr>\n</tbody></table></div>\n<div class=\"note\"><b>Wichtig:</b> Für genaue Präferendumsgrenzen braucht man ein genanntes Kriterium. Eine bestimmte prozentuale Leistungsschwelle ist keine allgemeingültige Definition.</div>"
      ],
      [
        "Überleben, Wachstum und Fortpflanzung",
        "<p>Ein Organismus kann am Leben bleiben, obwohl er kaum wächst oder sich nicht fortpflanzt. Diese drei Aussagen dürfen deshalb nicht gleichgesetzt werden.</p>\n<p><b>Überleben</b> bedeutet, dass lebensnotwendige Funktionen aufrechterhalten werden. <b>Wachstum</b> bedeutet eine Zunahme von Körpergröße oder Biomasse. Bei Pflanzen lässt sich der Aufbau neuer Substanz über die Trockenmasse erfassen: Dazu wird das enthaltene Wasser vor der Wägung entfernt. So wird eine bloße Änderung des Wassergehalts nicht mit Stoffzuwachs verwechselt.</p>\n<p><b>Erfolgreiche Fortpflanzung</b> ermöglicht Nachkommen. Eine blühende Pflanze hat sich noch nicht zwangsläufig erfolgreich fortgepflanzt: Bestäubung, Befruchtung und die Entwicklung keimfähiger Samen können weitere notwendige Schritte sein. Ohne Nachwuchs kann ein Bestand trotz noch lebender Einzelorganismen langfristig verschwinden.</p>\n<h3>Was eine Kurve aussagen kann</h3>\n<p>Eine Wachstumskurve zeigt zunächst Wachstum. Null Zuwachs beweist keinen Tod; ein positiver Zuwachs beweist keine Fortpflanzung. Für Überlebensgrenzen und Pessima braucht man passende zusätzliche Informationen. Unterschiede zwischen Lebensstadien sind ebenfalls möglich: Ein ausgewachsenes Tier kann Bedingungen überstehen, unter denen sich seine Eier nicht entwickeln.</p>\n<div class=\"note\"><b>Merke:</b> Lies eine Kurve immer bezogen auf ihre Messgröße. Übertrage ihre Grenzen nicht ungeprüft auf eine andere Lebensleistung.</div>"
      ]
    ]
  },
  {
    "id": "potenz",
    "title": "Konkurrenz & ökologische Potenz",
    "short": "Ökologische Potenz",
    "desc": "Wie begrenzte Ressourcen und Konkurrenz die Lebensmöglichkeiten einer Art verändern.",
    "source": "Konkurrenz, physiologische und ökologische Potenz (AB 3)",
    "sections": [
      [
        "Konkurrenz: begrenzte Ressourcen und ihre Folgen",
        "<p><b>Konkurrenz</b> entsteht, wenn Organismen dieselbe Ressource nutzen und deren Angebot nicht ausreicht, um den Bedarf aller uneingeschränkt zu decken. Nahrung, Wasser, Licht und Nistplätze können solche begrenzten Ressourcen sein. Ähnliche Ansprüche allein bedeuten noch keine starke Konkurrenz, solange das Angebot ausreichend ist.</p>\n<p><b>Intraspezifische Konkurrenz</b> besteht zwischen Individuen derselben Art, etwa zwischen zwei Rotbuchen um Licht. <b>Interspezifische Konkurrenz</b> besteht zwischen verschiedenen Arten, etwa zwischen einer Rotbuche und einer Waldkiefer.</p>\n<h3>Wie entsteht die Beeinträchtigung?</h3>\n<p>Nimmt eine Pflanze Wasser auf, steht dieses Wasser benachbarten Pflanzen nicht mehr zur Verfügung. Beschattet sie ihre Nachbarn, erreicht diese weniger Licht. Konkurrenz erfordert also weder direkten Körperkontakt noch einen sichtbaren Kampf. Weniger verfügbare Ressourcen können Wachstum, Überleben oder Fortpflanzung einschränken.</p>\n<p>Die Wirkung wird mit <b>−/−</b> beschrieben: Beide Beteiligten werden im Vergleich zu einer Situation ohne den jeweiligen Konkurrenten beeinträchtigt. Die Nachteile können sehr ungleich sein; eine Art kann ihre Ressourcen deutlich besser erschließen. Dass sie sich durchsetzt, macht die Beziehung nicht zu einem gegenseitigen Nutzen.</p>\n<div class=\"note\"><b>Konkurrenzstärke ist situationsabhängig:</b> Eine Art ist nicht unter allen Bedingungen überlegen. Verändert sich etwa die Bodenfeuchte, können sich die Konkurrenzverhältnisse ebenfalls verändern.</div>"
      ],
      [
        "Physiologische und ökologische Potenz",
        "<p>Ein Organismus kann einen Standort körperlich vertragen und dort dennoch durch Konkurrenz eingeschränkt werden. Die Unterscheidung zwischen physiologischer und ökologischer Potenz macht diesen Unterschied sichtbar.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Physiologische Potenz</th><th>Ökologische Potenz</th></tr></thead><tbody>\n<tr><td>Bereich eines abiotischen Faktors, in dem eine Art ohne einschränkende Konkurrenz dauerhaft überleben und sich fortpflanzen kann.</td><td>Bereich eines abiotischen Faktors, in dem dies unter den betrachteten Konkurrenzbedingungen möglich ist.</td></tr>\n<tr><td>Beschreibt die Möglichkeiten, die sich aus den körperlichen Eigenschaften der Art ergeben.</td><td>Berücksichtigt zusätzlich, dass andere Arten Ressourcen beanspruchen und die Lebensmöglichkeiten einschränken.</td></tr>\n</tbody></table></div>\n<p>Konkurrenz kann den nutzbaren Bereich verkleinern oder dessen günstigen Schwerpunkt verändern. Wie stark das geschieht, hängt vom Konkurrenten und den übrigen Bedingungen ab. Die ökologische Potenz ist deshalb keine überall gleichbleibende Eigenschaft unabhängig von der Lebensgemeinschaft.</p>\n<p><b>Verbindung zur Toleranzkurve:</b> Der reine Überlebensbereich kann auch Pessima enthalten. Dort ist Überleben möglich, Fortpflanzung aber nicht. Eine Aussage über dauerhaftes Bestehen mit Fortpflanzung benötigt deshalb mehr Informationen als den Nachweis kurzfristigen Überlebens.</p>\n<div class=\"note\"><b>Merke:</b> „Die Pflanze wächst“ belegt eine Lebensleistung. Es belegt allein noch nicht den vollständigen Bereich ihrer physiologischen oder ökologischen Potenz.</div>"
      ],
      [
        "Warum Vorkommen und Optimum nicht dasselbe sind",
        "<p>Das <b>tatsächliche Vorkommen</b> einer Art entsteht aus mehreren Einflüssen. Geeignete abiotische Bedingungen sind wichtig, reichen aber nicht immer aus. Konkurrenz, weitere Beziehungen zu Lebewesen und die Möglichkeit, einen Standort überhaupt zu erreichen, wirken ebenfalls mit.</p>\n<h3>Günstige Bedingungen können viele Konkurrenten anziehen</h3>\n<p>An einem gut versorgten Standort kann eine Pflanze ohne Konkurrenz besonders stark wachsen. Wenn dort andere Pflanzen Licht oder Wasser wirksamer nutzen, wird sie dennoch zurückgedrängt. An einem weniger günstigen Standort wächst sie vielleicht langsamer, trifft aber auf weniger Konkurrenz. So kann sie gerade dort häufiger vorkommen.</p>\n<p>Eine hohe Häufigkeit ist daher kein sicherer Beleg für das physiologische Optimum. Umgekehrt beweist das Fehlen einer Art nicht, dass sie die Temperatur oder Feuchte des Ortes grundsätzlich nicht verträgt.</p>\n<h3>Zusammenhänge fachlich deuten</h3>\n<p>Die Erklärung verbindet zwei Ebenen: Welche Bedingungen kann die Art selbst ertragen? Wie verändern andere Arten ihre Möglichkeiten? Verbessert sich ihre Entwicklung bei sonst vergleichbaren Bedingungen ohne Konkurrenten, spricht dies für eine Konkurrenzwirkung. Allein eine Verbreitungskarte erklärt die Ursache noch nicht.</p>\n<div class=\"note\"><b>Merke:</b> „Wo kommt eine Art häufig vor?“ und „Wo könnte sie ohne Konkurrenz am besten gedeihen?“ sind unterschiedliche Fragen.</div>"
      ]
    ]
  },
  {
    "id": "nische",
    "title": "Ökologische Nische & Koexistenz",
    "short": "Ökologische Nische",
    "desc": "Umweltansprüche, Ressourcennutzung und das Zusammenleben verschiedener Arten verstehen.",
    "source": "Lebensraum, Nischenüberlappung und Nischendifferenzierung (AB 4)",
    "sections": [
      [
        "Die ökologische Nische: mehr als ein Ort",
        "<p>Der <b>Lebensraum</b> bezeichnet den Ort, an dem eine Art lebt. Die <b>ökologische Nische</b> umfasst dagegen die Gesamtheit ihrer Umweltansprüche und Umweltbeziehungen. Sie beschreibt, unter welchen Bedingungen und durch welche Beziehungen eine Art leben kann.</p>\n<p>Dazu gehören abiotische Ansprüche, etwa an Temperatur und Feuchte, sowie biotische Beziehungen: Welche Nahrung wird genutzt? Welche Konkurrenten und Fressfeinde wirken auf die Art? Welche Partner unterstützen sie? Auch die Zeit und der Ort der Ressourcennutzung können bedeutsam sein.</p>\n<h3>Gleicher Lebensraum, unterschiedliche Nischen</h3>\n<p>Ein Eichhörnchen und ein Buntspecht können denselben Wald bewohnen. Allein der gemeinsame Ort sagt aber wenig darüber aus, welche Nahrung sie erschließen oder welche Strukturen sie zum Ruhen und zur Fortpflanzung benötigen. Für die Nische müssen mehrere solcher Merkmale zusammen betrachtet werden.</p>\n<p>Ein Körpermerkmal ist dabei nicht selbst die ganze Nische. Es kann aber erklären, welche Ressourcen zugänglich sind: Körpergröße, Schnabelform oder Beweglichkeit beeinflussen die Nutzungsmöglichkeiten.</p>\n<div class=\"note\"><b>Merke:</b> Die Nische ist kein abgetrennter Platz, den ein Tier „besitzt“. Sie beschreibt ein Gefüge aus Ansprüchen, Nutzung und Beziehungen.</div>"
      ],
      [
        "Nischenüberlappung und Nischendifferenzierung",
        "<p><b>Nischenüberlappung</b> liegt vor, wenn Arten teilweise dieselben Ansprüche haben oder dieselben Ressourcen nutzen. Nutzen zwei Vogelarten dieselben Samen, überlappen ihre Nischen hinsichtlich dieser Nahrung. Daraus folgt noch nicht, dass auch Nistplätze, Aktivitätszeiten und alle weiteren Ansprüche übereinstimmen.</p>\n<p>Ist die gemeinsam genutzte Ressource knapp, kann Konkurrenz entstehen. Wie stark diese ausfällt, hängt sowohl vom Ausmaß der Überlappung als auch vom verfügbaren Angebot ab.</p>\n<p><b>Nischendifferenzierung</b> bedeutet Unterschiede in der Ressourcennutzung. Arten können beispielsweise verschiedene Nahrung, verschiedene Bereiche eines Lebensraums oder verschiedene Nutzungszeiten haben. Dadurch beanspruchen sie eine begrenzte Ressource weniger gleichzeitig und beeinträchtigen sich schwächer.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Vergleichsmerkmal</th><th>Was unterschiedliche Nutzung bewirken kann</th></tr></thead><tbody>\n<tr><td>Nahrungsart oder Beutegröße</td><td>Ein geringerer Teil des Nahrungsangebots wird von beiden Arten beansprucht.</td></tr>\n<tr><td>Bereich der Nahrungssuche</td><td>Ressourcen aus verschiedenen Teilbereichen werden erschlossen.</td></tr>\n<tr><td>Zeit der Nutzung</td><td>Die gleichzeitige Nutzung kann abnehmen; ob Konkurrenz sinkt, hängt auch davon ab, wie schnell sich das Angebot erneuert.</td></tr>\n</tbody></table></div>\n<div class=\"note\"><b>Wichtig:</b> Differenzierung bedeutet keine bewusste Absprache. Unterschiede in Körperbau, Verhalten und Ansprüchen führen zu verschiedenen Nutzungsschwerpunkten.</div>"
      ],
      [
        "Koexistenz und Konkurrenzausschluss",
        "<p><b>Koexistenz</b> bedeutet, dass verschiedene Arten über längere Zeit nebeneinander bestehen. Nischendifferenzierung kann dies begünstigen: Je weniger die Arten dieselben knappen Ressourcen beanspruchen, desto geringer kann ihre gegenseitige Beeinträchtigung sein.</p>\n<p>Das <b>Konkurrenzausschlussprinzip</b> beschreibt die Grenze dieses Zusammenlebens: Arten mit gleichen Ansprüchen an dieselben begrenzten Ressourcen können unter dauerhaft gleichbleibenden Bedingungen nicht stabil nebeneinander bestehen, wenn eine Art die andere im Wettbewerb verdrängt. Die unterlegene Art kann dann lokal verschwinden.</p>\n<h3>Warum ähnliche Nahrung keine sichere Verdrängung bedeutet</h3>\n<p>In natürlichen Lebensräumen unterscheiden sich Arten oft in weiteren Ansprüchen. Zudem verändern sich Bedingungen räumlich und zeitlich. Zwei Arten können Nahrung teilen und dennoch unterschiedliche Rückzugsorte oder Nistmöglichkeiten nutzen. Überlappung in einem Merkmal beweist deshalb weder identische Nischen noch einen sicheren Konkurrenzausschluss.</p>\n<p>Wird ein Lebensraum vereinheitlicht, können unterschiedliche Nutzungsmöglichkeiten verloren gehen. Das kann die Überlappung und Konkurrenz verstärken. Ein strukturreicher Lebensraum kann umgekehrt mehr Ausweichmöglichkeiten bieten. Ob dadurch eine bestimmte Art erhalten bleibt, hängt von ihren konkreten Ansprüchen ab.</p>\n<div class=\"note\"><b>Merke:</b> Nischendifferenzierung kann Koexistenz erklären. Sie garantiert aber weder Konkurrenzfreiheit noch das Fortbestehen jeder Art.</div>"
      ]
    ]
  },
  {
    "id": "standort",
    "title": "Standortbedingungen & Artvorkommen",
    "short": "Standortanalyse",
    "desc": "Wie Pflanzenansprüche, Standort, Pflege und Blütenangebot zusammenhängen.",
    "source": "Standortfaktoren, Pflanzenansprüche und Bestäuberangebot (AB 5)",
    "sections": [
      [
        "Standortbedingungen und Pflanzenansprüche",
        "<p>Ein <b>Standort</b> wird durch das Zusammenwirken seiner Umweltbedingungen geprägt. Für Pflanzen sind unter anderem Licht, Temperatur, Wasser- und Mineralstoffversorgung sowie Eigenschaften des Bodens wichtig. Hinzu kommen Konkurrenz und Einflüsse durch Pflege oder Nutzung.</p>\n<p>Eine Pflanze kann nur dann gut gedeihen, wenn die Bedingungen zu ihren Ansprüchen passen. Viel Licht gleicht Wassermangel nicht automatisch aus. Ein feuchter Boden ist nicht für jede Art geeignet, wenn er gleichzeitig zu wenig Sauerstoff im Wurzelraum bereitstellt.</p>\n<h3>Standorte verändern sich</h3>\n<p>Unter Laubbäumen steht im Frühjahr vor dem Laubaustrieb häufig mehr Licht zur Verfügung als im Sommer. Auch Temperatur und Bodenfeuchte schwanken mit Wetter und Jahreszeit. Ein Messwert beschreibt deshalb zunächst die Situation am jeweiligen Ort und Zeitpunkt.</p>\n<p>Humus bezeichnet organische Bestandteile des Bodens, die aus der Zersetzung abgestorbenen Materials hervorgehen. Humus kann unter anderem die Wasserspeicherung beeinflussen. Die Angabe „humusreich“ ist jedoch noch keine Messung der für Pflanzen verfügbaren Mineralstoffe.</p>\n<div class=\"note\"><b>Beim Erklären des Vorkommens:</b> Verbinde einen Standortfaktor mit einem konkreten Anspruch der Art. „Sie wächst dort, weil es feucht ist“ erklärt erst dann etwas, wenn deutlich wird, weshalb die Pflanze diese Feuchte benötigt oder verträgt.</div>"
      ],
      [
        "Wuchsform, Pflege und Konkurrenz",
        "<p>Pflege verändert nicht nur die Höhe einer Pflanze, sondern auch ihre Lebensbedingungen und Konkurrenzbeziehungen. Ob eine Art Mähen oder Betreten verträgt, hängt unter anderem davon ab, wo ihre Blätter und erneuerungsfähigen Pflanzenteile liegen.</p>\n<p>Eine <b>Blattrosette</b> besteht aus dicht über dem Boden angeordneten Blättern. Beim Gänseblümchen bleiben diese bei einer nicht zu tiefen Mahd häufig erhalten, während höher stehende Blüten abgeschnitten werden können. Kriechende Triebe, beispielsweise beim Weißklee, können ebenfalls unterhalb der Schnitthöhe liegen. So ist erneutes Wachstum möglich.</p>\n<h3>Pflege kann gleichzeitig fördern und beeinträchtigen</h3>\n<p>Mahd entfernt Blätter und Blüten, hält aber auch hohe Konkurrenten niedrig. Niedrig wachsende Pflanzen können dadurch mehr Licht erhalten. Wird überhaupt nicht mehr gemäht, können hohe Gräser diese Pflanzen stärker beschatten. Wird sehr häufig gemäht, bleiben dagegen möglicherweise zu wenige Blüten erhalten.</p>\n<p>Betreten kann Pflanzenteile beschädigen und den Boden verdichten. Dabei verändern sich Porenraum, Belüftung und Wasserbewegung. Arten reagieren darauf unterschiedlich. Das Vorkommen einer trittverträglichen Art bedeutet nicht, dass Betreten für alle Pflanzen günstig ist.</p>\n<div class=\"note\"><b>Merke:</b> Eine Pflegemaßnahme wirkt direkt auf die Pflanze und indirekt über ihre Umwelt und Konkurrenten. Deshalb ist „mehr“ oder „weniger Pflege“ allein noch keine fachliche Begründung.</div>"
      ],
      [
        "Blüten, Bestäubung und Nahrungsangebot",
        "<p>Eine vorhandene Pflanze ist nicht automatisch eine aktuelle Nahrungsquelle für Bienen. Dafür müssen geeignete Blüten bzw. nutzbarer Pollen vorhanden und erreichbar sein.</p>\n<p><b>Nektar</b> ist eine zuckerhaltige Flüssigkeit und liefert vor allem Energie. <b>Pollen</b> enthält unter anderem Proteine und ist besonders für die Versorgung der Bienenlarven wichtig. Nicht jede Pflanze bietet beides an. Farne wie der Echte Wurmfarn bilden Sporen statt Blüten und Pollen; sie liefern daher weder Blütennektar noch Pollen.</p>\n<p>Bei der <b>Bestäubung</b> wird Pollen auf die Narbe einer Blüte derselben Pflanzenart übertragen. Dadurch kann die spätere Befruchtung ermöglicht werden. Blütenbesuch ist jedoch nicht automatisch wirksame Bestäubung: Entscheidend ist, ob geeigneter Pollen tatsächlich übertragen wird.</p>\n<h3>Vom Pflanzenbestand zum nutzbaren Angebot</h3>\n<p>Standorteignung ermöglicht Wachstum; eine passende Pflege lässt Blüten entstehen und bestehen. Die Blütezeit bestimmt, wann Nahrung verfügbar sein kann. Verschiedene Blütezeiten können einander ergänzen. Wetter, Mahd und der tatsächliche Blütenbestand entscheiden mit, ob das Angebot in einem bestimmten Zeitraum wirklich vorhanden ist.</p>\n<div class=\"note\"><b>Fachlich abwägen:</b> Eine geeignete Maßnahme verbindet Pflanzenansprüche, tatsächliches Blütenangebot und Flächennutzung. Eine lange mögliche Blütezeit allein garantiert keine durchgängige Versorgung.</div>"
      ]
    ]
  },
  {
    "id": "symbiose",
    "title": "Symbiose: gegenseitiger Nutzen",
    "short": "Symbiose",
    "desc": "Wie verschiedene Arten voneinander profitieren und wie dieser Nutzen entsteht.",
    "source": "gegenseitiger Nutzen in interspezifischen Beziehungen (AB 6; ergänzend Pflanzenprofile aus AB 5)",
    "sections": [
      [
        "Was Symbiose bedeutet",
        "<p><b>Symbiose</b> bezeichnet hier im engeren, im Unterricht verwendeten Sinn eine Beziehung zwischen verschiedenen Arten, von der beide Partner profitieren. Die Wirkung wird mit <b>+/+</b> angegeben. Das erste und das zweite Plus stehen jeweils für den Vorteil eines Partners.</p>\n<p>Ein Vorteil kann darin bestehen, leichter Nahrung zu erhalten, besser vor Feinden geschützt zu sein oder günstigere Bedingungen für Wachstum und Fortpflanzung zu haben. Beide Partner müssen weder dieselbe Leistung erbringen noch gleich stark profitieren.</p>\n<h3>Vorteil und Leistung unterscheiden</h3>\n<p>Was ein Partner tut, ist nicht automatisch sein eigener Nutzen. Baut ein Tier einen gemeinsamen Rückzugsort, ist der Bau seine Leistung. Der Vorteil des anderen Partners liegt im Zugang zu diesem Schutzraum. Für eine vollständige Erklärung muss anschließend auch der Nutzen des bauenden Tieres benannt werden.</p>\n<p>Die Bezeichnung beschreibt keine bewusste Hilfsbereitschaft. Ein Verhalten oder Stoffaustausch kann für beide Arten vorteilhaft sein, ohne dass sie dies beabsichtigen. Ebenso bedeutet gegenseitiger Nutzen nicht automatisch, dass keiner der Partner ohne den anderen leben könnte.</p>\n<div class=\"note\"><b>Merke:</b> Räumliche Nähe oder gemeinsames Auftreten allein reichen nicht für Symbiose. Entscheidend sind nachvollziehbare Vorteile für beide beteiligten Arten.</div>"
      ],
      [
        "Wie gegenseitiger Nutzen entsteht",
        "<p>Partner können unterschiedliche Fähigkeiten oder Stoffwechselleistungen besitzen. Durch ihre Beziehung werden Ressourcen oder Leistungen zugänglich, die ein Partner allein schlechter erschließen könnte.</p>\n<h3>Stoffe austauschen</h3>\n<p>Weißklee lebt mit Knöllchenbakterien in seinen Wurzeln zusammen. Diese können Luftstickstoff in Verbindungen überführen, die für die Pflanze nutzbar sind. Stickstoff wird beispielsweise für den Aufbau von Proteinen benötigt. Die Bakterien erhalten von der Pflanze energiereiche organische Stoffe. Die unterschiedlichen Stoffwechselleistungen erklären somit den Vorteil auf beiden Seiten.</p>\n<h3>Eine Leistung nutzen</h3>\n<p>Bei einer Beziehung zwischen Blütenpflanze und Bestäuber kann das Tier Nahrung erhalten, während es Pollen zwischen Blüten überträgt. Der Vorteil der Pflanze liegt in der ermöglichten Fortpflanzung, nicht darin, dass ihre Nahrungsvorräte verbraucht werden. Für den gegenseitigen Nutzen muss der Besuch tatsächlich zur Bestäubung beitragen.</p>\n<p>Andere Beziehungen beruhen auf Schutz oder Warninformationen. Hier ist die Wirkungskette entscheidend: Eine Leistung verändert eine Bedingung für den Partner; dadurch sinkt beispielsweise dessen Gefährdung.</p>\n<div class=\"note\"><b>Erklärmuster:</b> Partner A stellt eine bestimmte Leistung bereit → diese verbessert eine Lebensbedingung von B. Anschließend muss die umgekehrte Richtung erklärt werden.</div>"
      ],
      [
        "Nutzen einordnen und Abhängigkeiten verstehen",
        "<p>Der Nutzen einer Beziehung wird durch einen passenden Vergleich deutlich: Wie ergeht es dem Partner unter vergleichbaren Bedingungen mit und ohne die Beziehung? Dabei können etwa Nahrungsversorgung, Schutz, Wachstum oder Fortpflanzung betrachtet werden.</p>\n<p>Ein Partner muss ohne den anderen nicht sofort sterben, damit ein Vorteil vorliegt. Bereits eine geringere Gefährdung oder bessere Versorgung kann bedeutsam sein. Umgekehrt beweist ein gemeinsames Auftreten noch keinen solchen Vorteil.</p>\n<h3>Vorteile können mit Aufwand verbunden sein</h3>\n<p>Eine Pflanze gibt bei einem Stoffaustausch beispielsweise einen Teil ihrer aufgebauten organischen Stoffe ab. Dieser Aufwand kann sich lohnen, wenn sie dafür einen benötigten Stoff erhält. „Nutzen“ bedeutet daher nicht, dass die Beziehung keinerlei Kosten verursacht, sondern dass sie unter den betrachteten Bedingungen insgesamt vorteilhaft ist.</p>\n<p>Wie stark Partner aufeinander angewiesen sind, kann unterschiedlich sein. Auch die Umweltbedingungen spielen eine Rolle: Eine zusätzliche Versorgung ist besonders bedeutsam, wenn die betreffende Ressource knapp ist. Ein Vorteil unter einer Bedingung darf deshalb nicht ungeprüft auf jede Situation übertragen werden.</p>\n<div class=\"note\"><b>Zur Abgrenzung:</b> Bei Symbiose profitieren beide. Profitiert nur ein Partner auf Kosten des anderen, ist die Beziehung nicht allein wegen des engen Zusammenlebens eine Symbiose im hier verwendeten Sinn.</div>"
      ]
    ]
  },
  {
    "id": "parasitismus",
    "title": "Parasitismus: Nutzen auf Kosten des Wirts",
    "short": "Parasitismus",
    "desc": "Wie Parasiten ihren Wirt nutzen, Schäden entstehen und Beziehungen eingeordnet werden.",
    "source": "Parasit und Wirt, Schaden und Abgrenzung zur Symbiose (AB 7)",
    "sections": [
      [
        "Parasit und Wirt",
        "<p>Beim <b>Parasitismus</b> nutzt ein Lebewesen ein anderes als Nahrungsquelle und/oder Lebensraum und schädigt es dabei. Das profitierende Lebewesen heißt <b>Parasit</b>, das geschädigte Lebewesen <b>Wirt</b>. Die Beziehung wird mit <b>+/−</b> beschrieben.</p>\n<p>Parasiten können zeitweise oder über längere Abschnitte ihres Lebens mit einem Wirt verbunden sein. Der Wirt kann dabei weiterleben. Sein unmittelbarer Tod ist weder Voraussetzung noch das entscheidende Kennzeichen des Parasitismus.</p>\n<h3>Was als Schaden zählt</h3>\n<p>Schäden können der Entzug von Nährstoffen, die Verletzung von Gewebe oder die Beeinträchtigung einer Körperfunktion sein. Auch eine verringerte Entwicklung oder Fortpflanzung ist biologisch bedeutsam, selbst wenn der Wirt äußerlich noch aktiv wirkt.</p>\n<p>Nutzen und Schaden müssen auf beide Partner bezogen werden: Für den Parasiten kann die Beziehung eine zuverlässige Versorgung bieten. Dem Wirt fehlen dadurch Stoffe oder funktionsfähige Körperteile. Dass der Parasit den Wirt zum Überleben benötigt, macht die Beziehung nicht automatisch für den Wirt vorteilhaft.</p>\n<div class=\"note\"><b>Merke:</b> „Der Wirt lebt noch“ widerlegt Parasitismus nicht. Entscheidend ist, ob der Parasit profitiert und der Wirt gegenüber einer geeigneten Situation ohne Befall beeinträchtigt ist.</div>"
      ],
      [
        "Vom Befall zur biologischen Schädigung",
        "<p>Eine biologische Erklärung nennt nicht nur einen sichtbaren Schaden, sondern verbindet den Befall mit dem betroffenen Körpervorgang.</p>\n<h3>Stoffentzug</h3>\n<p>Nutzt ein Parasit Nährstoffe des Wirts, stehen diese dem Wirt nicht mehr im gleichen Umfang für den eigenen Stoffwechsel zur Verfügung. Je nach Ausmaß kann dadurch weniger Energie oder Baumaterial für Wachstum, Reparatur und Fortpflanzung verfügbar sein.</p>\n<h3>Gewebe- und Funktionsschäden</h3>\n<p>Wird ein Gewebe verletzt oder seine Versorgung gestört, können Zellen ihre Aufgaben schlechter erfüllen. Eine gestörte Blutversorgung kann beispielsweise den Transport von Sauerstoff und Nährstoffen zu einem Gewebe verringern. Die eingeschränkte Zellfunktion kann schließlich die Funktion eines ganzen Körperteils beeinträchtigen.</p>\n<p>Wie stark die Schädigung ausfällt, hängt unter anderem von der Zahl der Parasiten, der Dauer des Befalls, dem betroffenen Gewebe und dem Zustand des Wirts ab. Eine geringe äußerlich sichtbare Veränderung schließt eine Beeinträchtigung nicht aus.</p>\n<div class=\"note\"><b>Erklärmuster:</b> Tätigkeit oder Wirkung des Parasiten → veränderter Körpervorgang beim Wirt → Folge für dessen Lebensleistung. Welche Kette zutrifft, muss zum beschriebenen Parasiten passen; nicht jeder Parasit verursacht jeden dieser Schäden.</div>"
      ],
      [
        "Symbiose, Parasitismus und Konkurrenz abgrenzen",
        "<p>Zur Einordnung einer Beziehung wird die Wirkung für <b>jeden Beteiligten</b> betrachtet. Maßgeblich ist der Vergleich mit einer geeigneten Situation ohne diese Beziehung.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Beziehung</th><th>Wirkung</th><th>Fachliches Kriterium</th></tr></thead><tbody>\n<tr><td>Symbiose im engeren Sinn</td><td>+/+</td><td>Beide Arten haben einen Vorteil, etwa durch Stoffaustausch oder Schutz.</td></tr>\n<tr><td>Parasitismus</td><td>+/−</td><td>Der Parasit profitiert; der Wirt wird durch seine Nutzung geschädigt.</td></tr>\n<tr><td>Konkurrenz</td><td>−/−</td><td>Die Nutzung derselben begrenzten Ressource beeinträchtigt beide, möglicherweise unterschiedlich stark.</td></tr>\n</tbody></table></div>\n<h3>Eine teilweise Entlastung ist nicht automatisch ein Vorteil</h3>\n<p>Ein befallener Wirt kann trotz einer Schädigung noch Nahrung aufnehmen oder eine beeinträchtigte Funktion teilweise ausgleichen. Das zeigt zunächst, dass die Schädigung nicht jede Funktion vollständig verhindert. Es belegt nicht, dass der Wirt insgesamt besser gestellt ist als ohne Befall.</p>\n<p>Auch ein einzelner positiver Effekt darf nicht isoliert betrachtet werden. Für die Einordnung sind die begründbaren Gesamtfolgen wichtig. Sind diese nicht ausreichend bekannt, bleibt eine Aussage vorläufig.</p>\n<div class=\"note\"><b>Merke:</b> Vergleiche einen befallenen Wirt nicht nur mit einem noch schwerer geschädigten Wirt. Eine passende Vergleichssituation ohne Befall ist nötig, um einen behaupteten Nutzen zu beurteilen.</div>"
      ]
    ]
  }
],exercises:[],exams:[]};
const add=(topic,id,title,type,prompt,body)=>GK.exercises.push({topic,id,title,type,prompt,...body});
add('oekosystem','aquarium','Das Aquarium zuordnen','match','Ordne jeden Bestandteil dem Biotop oder der Biozönose zu.',{options:['Biotop','Biozönose'],items:[['Sauerstoffgehalt','Biotop','Der Sauerstoffgehalt ist eine unbelebte Umweltbedingung.'],['Wasserpflanzen','Biozönose','Pflanzen sind Lebewesen.'],['Bakterien im Bodengrund','Biozönose','Auch mikroskopisch kleine Lebewesen gehören zur Lebensgemeinschaft.'],['Wassertemperatur','Biotop','Temperatur ist eine abiotische Bedingung.'],['Schnecken','Biozönose','Schnecken sind Teil der Lebensgemeinschaft.'],['Mineralstoffgehalt','Biotop','Gelöste Mineralstoffe sind unbelebte Bestandteile.']]});
add('oekosystem','faktoren','Ressource oder Wechselwirkung?','match','Ordne die beschriebenen Einflüsse zu.',{options:['Abiotischer Faktor','Biotische Wechselwirkung'],items:[['Zwei Wasserpflanzen beschatten einander','Biotische Wechselwirkung','Lebewesen beeinflussen sich: Konkurrenz um Licht.'],['Die Wassertemperatur beträgt 20 °C','Abiotischer Faktor','Temperatur gehört zur unbelebten Umwelt.'],['Fische fressen kleine Schnecken','Biotische Wechselwirkung','Fraß ist eine Beziehung zwischen Organismen.'],['Zwei Pflanzen konkurrieren um Wasser','Biotische Wechselwirkung','Die Wechselwirkung bleibt biotisch, obwohl Wasser abiotisch ist.']]});
add('oekosystem','system','Ein künstliches Ökosystem?','multi','Wähle alle fachlich richtigen Aussagen aus.',{choices:[['Ein Aquarium kann trotz menschlicher Pflege ein Ökosystem sein.',true,'Entscheidend sind Biotop, Biozönose und Wechselwirkungen.'],['Biotop und Biozönose beeinflussen sich gegenseitig.',true,'Organismen verändern beispielsweise den Sauerstoffgehalt.'],['Ein Ökosystem muss ohne jeden Energieaustausch bestehen.',false,'Ökosysteme stehen im Austausch mit ihrer Umgebung.'],['Alle Fische verschiedener Arten bilden zusammen eine Population.',false,'Eine Population umfasst Individuen einer Art.']]});
add('toleranz','kurve','Die Toleranzkurve untersuchen','curve','Verschiebe den Regler. Prüfe danach die vier Angaben zur Kurve und zur zusätzlichen Langzeitbeobachtung.',{items:[['Optimum des Trockenmassezuwachses (%)',60,'Bei 60 % ist der Zuwachs mit 2,5 g maximal.'],['Unterste Bodenfeuchte mit Überleben (%)',15,'Die zusätzliche Beobachtung nennt 15 % als Minimum.'],['Oberste Bodenfeuchte mit Überleben (%)',95,'95 % ist die obere Überlebensgrenze im Modell.'],['Zuwachs bei 60 % Bodenfeuchte (g)',2.5,'Lies die y-Achse ab: 2,5 g.']]});
add('toleranz','begriffe','Die Bereiche einer Toleranzkurve','match','Ordne die Beschreibungen den passenden Begriffen zu.',{options:['Optimum','Präferendum','Pessimum','Toleranzbereich','Minimum'],items:[['Überleben möglich, aber keine keimfähigen Samen','Pessimum','Pessima liegen an den Rändern des Überlebensbereichs.'],['Faktorwert mit höchster gemessener Leistung','Optimum','Das Optimum ist ein Faktorwert, kein breiter Bereich.'],['Besonders günstiger Bereich um das Optimum','Präferendum','Exakte Grenzen brauchen ein festgelegtes Kriterium.'],['Gesamter Bereich, in dem Überleben möglich ist','Toleranzbereich','Dazu gehören auch die Pessima.'],['Untere Grenze des Überlebensbereichs','Minimum','Unterhalb des Minimums ist dauerhaftes Überleben unmöglich.']]});
add('toleranz','versuch','Was belegen die Daten?','multi','Wähle alle Aussagen, die mit dem Bohnenmodell vereinbar sind.',{choices:[['0 g Zuwachs bei 15 % beweist den Tod der Pflanze.',false,'Die Langzeitbeobachtung zeigt dort Überleben ohne keimfähige Samen.'],['Licht und Temperatur sollen im Feuchteversuch vergleichbar sein.',true,'Sonst wäre der Einfluss der Bodenfeuchte schwerer zu isolieren.'],['Ein höherer Wasseranteil kann den luftgefüllten Porenraum verringern.',true,'Wurzeln benötigen Sauerstoff für die Zellatmung.'],['Die Präferendumsgrenzen lassen sich aus der Kurve auf exakt 40 und 80 % festlegen.',false,'Ein entsprechendes Abgrenzungskriterium fehlt.'],['Für Aussagen über Fortpflanzung sind Daten zur Samenbildung nötig.',true,'Wachstum allein reicht nicht.']]});
add('potenz','kiefer','Den Konkurrenzeffekt berechnen','numeric','Berechne anhand der Tabelle die Abnahme der Wuchsleistung der Kiefer: Wert allein minus Wert mit Buche.',{material:pineTable+'<p class="source">Relative Wuchsleistung (0–10), didaktisch modellierte Daten.</p>',items:[['Abnahme bei 45 % Bodenfeuchte',6,'9 − 3 = 6 Einheiten.'],['Abnahme bei 60 % Bodenfeuchte',9,'10 − 1 = 9 Einheiten.'],['Abnahme bei 90 % Bodenfeuchte',0,'4 − 4 = 0 Einheiten.']]});
add('potenz','potenzbegriffe','Welcher Befund trägt welche Aussage?','match','Ordne die Untersuchungen ihrer Aussagekraft zu.',{options:['Physiologische Potenz','Ökologische Potenz','Nur kurzfristige Wuchsleistung'],items:[['Dauerhaftes Überleben und Fortpflanzung ohne Konkurrenz untersucht','Physiologische Potenz','Beide Kriterien werden ohne Konkurrenz geprüft.'],['Dauerhaftes Überleben und Fortpflanzung unter Konkurrenz untersucht','Ökologische Potenz','Die Konkurrenzbedingungen gehören zur Aussage.'],['Vier Wochen lang nur den Zuwachs gemessen','Nur kurzfristige Wuchsleistung','Fortpflanzung ist damit nicht belegt.']]});
add('potenz','konkurrenz','Intra oder inter?','match','Ordne die Konkurrenzsituationen zu.',{options:['Intraspezifisch','Interspezifisch'],items:[['Zwei Waldkiefern konkurrieren um Wasser','Intraspezifisch','Beide gehören derselben Art an.'],['Waldkiefer und Rotbuche konkurrieren um Licht','Interspezifisch','Zwei verschiedene Arten nutzen dieselbe begrenzte Ressource.'],['Zwei Blaumeisen konkurrieren um einen Nistkasten','Intraspezifisch','Es konkurrieren Individuen derselben Art.'],['Kohlmeise und Blaumeise konkurrieren um Nahrung','Interspezifisch','Die Konkurrenz findet zwischen Arten statt.']]});
add('nische','nischenbegriffe','Ort, Ansprüche, Unterschiede','match','Ordne die Aussagen den Begriffen zu.',{options:['Lebensraum','Ökologische Nische','Nischenüberlappung','Nischendifferenzierung'],items:[['Beide Vogelarten leben im selben Garten','Lebensraum','Die Aussage beschreibt den Ort.'],['Gesamtheit der Umweltansprüche und -beziehungen','Ökologische Nische','Die Nische ist ein Wirkungsgefüge.'],['Beide Arten nutzen dieselben Samen am Futterhaus','Nischenüberlappung','Bei dieser Ressource überschneiden sich die Ansprüche.'],['Eine Art sucht häufiger außen an dünnen Zweigen, die andere an stärkeren Ästen','Nischendifferenzierung','Unterschiedliche Ressourcennutzung kann Konkurrenz verringern.']]});
add('nische','meisen','Nischenprofile rekonstruieren','match','Ordne die typischen Beobachtungen zu. Beachte: Es geht um Schwerpunkte, nicht um starre Grenzen.',{options:['Eher Kohlmeise','Eher Blaumeise','Beide Arten'],items:[['Kleiner und leichter; erreicht feine äußere Zweige gut','Eher Blaumeise','Der Körperbau ermöglicht diesen Nutzungsschwerpunkt.'],['Sucht häufiger auch am Boden und an kräftigen Ästen','Eher Kohlmeise','Die größere Kohlmeise nutzt diese Bereiche häufiger.'],['Kann Sonnenblumenkerne am Futterhaus nutzen','Beide Arten','Die Nahrungsspektren überlappen.'],['Passt durch eine Nistkastenöffnung von etwa 26–28 mm','Eher Blaumeise','Die größere Kohlmeise passt nicht durch diese kleine Öffnung.']]});
add('nische','umbau','Ein Garten wird vereinheitlicht','multi','Im Garten werden feine äußere Zweige entfernt und nur noch Nistkästen mit 32-mm-Öffnungen angeboten. Wähle alle begründeten Folgerungen.',{choices:[['Die Blaumeise verliert einen typischen Bereich ihrer Nahrungssuche.',true,'Feine äußere Zweige sind für sie besonders gut nutzbar.'],['Die Überlappung beim Zugang zu Nistkästen kann zunehmen.',true,'Beide Arten können die größeren Öffnungen nutzen.'],['Die Blaumeise wird zwangsläufig vollständig aussterben.',false,'Dafür fehlen Daten zu Ausweichmöglichkeiten und Bestandsentwicklung.'],['Unterschiedliche Ressourcenangebote können Koexistenz begünstigen.',true,'Sie können die Überlappung begrenzter Ressourcen reduzieren.']]});
add('standort','pflanzen','Nektar, Pollen oder keines von beiden?','match','Ordne die sechs Pflanzen nach dem Nahrungsangebot aus den Profilen zu.',{options:['Nektar und Pollen','Pollen, aber kein Nektar','Weder Nektar noch Pollen'],items:[['Gänseblümchen','Nektar und Pollen','Das Angebot besteht nur, wenn Blüten vorhanden sind.'],['Breitwegerich','Pollen, aber kein Nektar','Er wird vorwiegend windbestäubt; Bienen können Pollen sammeln.'],['Echter Wurmfarn','Weder Nektar noch Pollen','Farne bilden Sporen, keine Blüten und keinen Pollen.'],['Weißklee','Nektar und Pollen','Blütenstände können durch Mahd entfernt werden.'],['Kleine Braunelle','Nektar und Pollen','Ihre Blütentriebe müssen stehen bleiben.'],['Geflecktes Lungenkraut','Nektar und Pollen','Es ergänzt das Angebot im Frühjahr.']]});
add('standort','pflege','Eine Maßnahme auswählen','scenario','Die Mitte der Rasenfläche muss als Pausenfläche erhalten bleiben. Welche der folgenden Maßnahmen erfüllt die Kriterien Standorteignung, Blütenangebot und Nutzung am besten?',{material:siteTable,choices:[['Gesamte Rasenfläche mit Wurmfarn bepflanzen','Der Wurmfarn passt schlecht zur offenen, mäßig trockenen Fläche und bietet weder Nektar noch Pollen. Außerdem geht die Pausenfläche verloren.'],['Sonnigen Randstreifen mit vorhandenen Blütenpflanzen abschnittsweise später mähen; Mitte weiter nutzen','Die Maßnahme lässt Blüten stehen und erhält die Nutzung. Prüfe zusätzlich Bodenfeuchte, Artenbestand und die Wirkung auf hohe Gräser.'],['Überall unverändert alle zwei Wochen kurz mähen','Das erhält die Nutzung, kann aber weiterhin Blüten entfernen und verbessert das Nahrungsangebot nicht gezielt.']],answer:1});
add('standort','messdaten','Befund oder unzulässiger Schluss?','multi','Wähle alle Aussagen, die sich mit den Standortdaten begründen lassen.',{material:siteTable,choices:[['A war um 12 Uhr heller und wärmer als B.',true,'42.000 statt 3.500 Lux und 22 statt 17 °C belegen dies für den Messzeitpunkt.'],['Der Nährstoffgehalt wurde an beiden Standorten bestimmt.',false,'Die Nährstoffversorgung wurde ausdrücklich nicht untersucht.'],['B ist an jedem Tag des Jahres gleich dunkel.',false,'Vor Laubaustrieb ist B heller; zudem ändern sich Wetter und Sonnenstand.'],['Mahdtoleranz garantiert kein ununterbrochenes Blütenangebot.',true,'Blätter können überleben, während Blüten abgeschnitten werden.']]});
add('symbiose','warnkette','Wie gelangt die Warnung zum Krebs?','order','Bringe die Vorgänge in die richtige Reihenfolge.',{items:['Gefahr erscheint in der Umgebung.','Die Grundel erkennt die Gefahr mit ihren Augen.','Die Grundel führt zitternde Bewegungen aus.','Der Krebs nimmt die Bewegung über den Fühlerkontakt wahr.','Der Krebs kann sich in die Höhle zurückziehen.'],explanation:'Das Signal wird von der Grundel über Bewegung und Körperkontakt übertragen. Der Krebs muss die Gefahr dafür nicht selbst sehen.'});
add('symbiose','nutzen','Wer leistet was, wer profitiert?','match','Ordne die Aussagen dem passenden Tier zu.',{options:['Grundel','Knallkrebs','Beide'],items:[['Baut und unterhält die Höhle','Knallkrebs','Der Krebs bewegt Sand und kleine Gesteinsteilchen.'],['Erkennt Gefahren durch gutes Sehvermögen','Grundel','Die Grundel beobachtet die Umgebung.'],['Erhält Warninformationen über einen Fühler','Knallkrebs','Er hält Körperkontakt zur Grundel.'],['Kann die Höhle als Rückzugsort nutzen','Beide','Die Höhle schützt beide Tiere.']]});
add('symbiose','bildbeweis','Was zeigt ein Bild wirklich?','multi','Ein Bild zeigt Grundel und Krebs mit Fühlerkontakt am Höhleneingang. Wähle alle fachlich tragfähigen Aussagen.',{choices:[['Das Bild kann räumliche Nähe und Kontakt zeigen.',true,'Diese Merkmale sind im Bild darstellbar.'],['Das Bild allein beweist die Übertragung einer Warnung.',false,'Dafür sind Beobachtungen eines zeitlichen Ablaufs nötig.'],['Für Symbiose muss ein Nutzen für beide Partner begründet werden.',true,'Ein Zusammenleben allein reicht nicht.'],['Der Höhlenbau und die Warnfunktion erklären unterschiedliche Vorteile.',true,'Die Grundel erhält Schutzraum, der Krebs Warninformationen.']]});
add('parasitismus','asselkette','Vom Anheften zum Gewebeschaden','order','Ordne die Schritte der im Material beschriebenen Erklärung.',{items:['Die Assel heftet sich an die Zunge.','Die Blutversorgung des Zungengewebes wird geschädigt.','Das Gewebe erhält weniger Sauerstoff und Nährstoffe.','Das Zungengewebe verkümmert.','Die Assel bleibt am Zungenstumpf und Mundboden befestigt.'],explanation:'Die Kette gibt die gängige Erklärung des Unterrichtsmaterials wieder. Hakenförmige Beinenden ermöglichen die Befestigung.'});
add('parasitismus','belege','Befund, Vermutung oder offene Frage?','match','Ordne die Aussagen aus dem Assel-Material ein.',{options:['Beobachteter Befund','Begründete Vermutung','Offene Frage','Nicht belegte Behauptung'],items:[['Zwei befallene Fische hatten trotz starkem Zungenverlust Nahrung aufgenommen.','Beobachteter Befund','Dies wurde in der beschriebenen Untersuchung festgestellt.'],['Die Assel kann einen Teil der mechanischen Funktion ersetzen.','Begründete Vermutung','Die Nahrungsaufnahme trotz Zungenverlust stützt diese Deutung.'],['Wovon ernährt sich die erwachsene Assel genau?','Offene Frage','Die genaue Ernährung ist nicht abschließend geklärt.'],['Befallene Fische leben besser als gesunde Fische.','Nicht belegte Behauptung','Ein Vorteil gegenüber gesunden Fischen wurde nicht nachgewiesen.']]});
add('parasitismus','beziehungen','Beziehungen mit Vorzeichen einordnen','match','Ordne die Wirkungen zu. Das erste Vorzeichen gehört jeweils zum zuerst genannten Partner.',{options:['+/+','+/−','−/−'],items:[['Grundel / Knallkrebs','+/+','Beide erhalten einen begründbaren Nutzen.'],['Assel / Fisch','+/−','Die Assel profitiert; der Fisch erleidet Gewebeschaden.'],['Waldkiefer / Rotbuche bei Konkurrenz','−/−','Beide werden gegenüber dem Wachstum allein beeinträchtigt, aber nicht gleich stark.']]});

const q=(title,prompt,solution,afb)=>({title,prompt,solution,afb});
GK.exams=[
{id:'bohnen',topic:'toleranz',title:'Wie viel Wasser ist günstig?',desc:'Toleranzkurven auswerten, Standorte einordnen und eine Behauptung beurteilen.',source:'Aufgaben neu formuliert auf Grundlage von AB 2; unveränderte didaktische Modelldaten.',materials:[['Material 1 · Ein kontrollierter Feuchteversuch',`<p>Gleich alte Bohnenpflanzen wachsen vier Wochen bei konstant gehaltener Bodenfeuchtigkeit. Licht, Temperatur, Boden und Nährstoffangebot sind gleich. Je Feuchtestufe werden mehrere Pflanzen untersucht. Die Feuchte bezeichnet den wassergefüllten Anteil des Porenraums. Gemessen wird der mittlere Zuwachs der Trockenmasse.</p>${beans()}${beanTable}`],['Material 2 · Längere Beobachtung',`<p>Weitere Pflanzen derselben Versuchsgruppen werden bis zur möglichen Fruchtbildung beobachtet. Unter 15 % und über 95 % sterben sie dauerhaft ab. Bei 15–25 % sowie 85–95 % überleben sie, bilden aber keine keimfähigen Samen. Bei mehr als 25 % und weniger als 85 % sind Wachstum und keimfähige Samen möglich.</p><p>Auch Wurzeln benötigen Sauerstoff für die Zellatmung. Sauerstoff gelangt über luftgefüllte Poren im Boden zu ihnen.</p>`]],questions:[q('Kurvenverlauf','Beschreiben Sie den Verlauf in Material 1. Belegen Sie Anstieg, Maximum und Abfall mit Zahlenwerten.','Der Zuwachs steigt von 0 g bei 15 % über 1,2 g bei 40 % auf 2,5 g bei 60 %. Danach fällt er über 1,2 g bei 80 % auf 0 g bei 95 %. Das gemessene Wachstumsoptimum liegt bei 60 % Bodenfeuchte.','I'),q('Toleranz und Fortpflanzung','Ermitteln Sie mit Material 2 Minimum, Maximum und beide Pessima. Erklären Sie, warum diese Angaben nicht allein aus Material 1 folgen.','Minimum: 15 %, Maximum: 95 %. Pessima: 15–25 % und 85–95 %. Dort überleben Pflanzen, bilden aber keine keimfähigen Samen. Material 1 erfasst nur Trockenmassezuwachs über vier Wochen; es misst weder dauerhafte Überlebensfähigkeit noch Samenbildung.','II'),q('Standorte einordnen','Vergleichen Sie anhand beider Materialien Standorte mit 20 %, 60 % und 90 % Bodenfeuchte hinsichtlich Wachstum und Fortpflanzung. Erläutern Sie, an welchem Standort sich ein Bestand unter den Modellbedingungen durch keimfähige Samen erneuern kann.','20 % liegen im unteren, 90 % im oberen Pessimum. Die Pflanzen überleben dort, bilden aber keine keimfähigen Samen; bei 90 % ist der Zuwachs mit 0,1 g sehr gering. 60 % liegen am gemessenen Wachstumsoptimum von 2,5 g und im Fortpflanzungsbereich. Dort ist die Erneuerung durch keimfähige Samen möglich. In den Pessima ist Überleben einzelner Pflanzen nicht mit erfolgreicher Fortpflanzung gleichzusetzen.','II'),q('Eine Behauptung beurteilen','Beurteilen Sie die Aussage „Je mehr Wasser, desto besser wachsen Bohnen“. Beziehen Sie beide Materialien ein.','Die pauschale Aussage ist falsch. Oberhalb des gemessenen Optimums von 60 % sinkt der Zuwachs, etwa auf 0,1 g bei 90 %. Hohe Wassersättigung verringert luftgefüllten Porenraum; dadurch kann die Sauerstoffversorgung der Wurzeln und ihre Zellatmung eingeschränkt werden. Material 2 zeigt zudem fehlende Samenbildung im oberen Pessimum und Tod oberhalb von 95 %. Der Sauerstoffmangel ist eine plausible Erklärung, wurde im Versuch aber nicht direkt gemessen.','III')]},
{id:'wald',topic:'potenz',title:'Waldkiefer und Rotbuche',desc:'Konkurrenzdaten und langfristiges Vorkommen gemeinsam deuten.',source:'Aufgaben neu formuliert nach AB 3. Alle Wachstums- und Häufigkeitsangaben sind didaktisch modelliert.',materials:[['Material 1 · Getrennte und gemeinsame Kultur',`<p>Junge Bäume wachsen bei sechs konstanten Bodenfeuchten getrennt oder gemeinsam. Licht, Temperatur, Nährstoffangebot und Versuchsdauer sind vergleichbar. Gemessen wird die relative Wuchsleistung auf einer Skala von 0 bis 10. Diese Messgröße zeigt nicht unmittelbar Fortpflanzung oder dauerhaftes Überleben.</p>${pineTable}<figure>${chart([15,30,45,60,75,90],[{label:'Kiefer allein',values:[3,6,9,10,8,4],color:'#087c88'},{label:'Kiefer mit Buche',values:[3,5,3,1,2,4],color:'#a86d32'}],10,'Relative Wuchsleistung (0–10)','Bodenfeuchtigkeit in %')}<figcaption>Wuchsleistung der Kiefer, Werte aus der Tabelle. Didaktisch modelliert.</figcaption></figure>`],['Material 2 · Langjährige Modellkartierung',table(['Bodenfeuchte (%)',15,30,45,60,75,90],[['Kiefer','häufig','häufig','selten','selten','selten','häufig'],['Buche','fehlt','selten','häufig','sehr häufig','häufig','fehlt']])+'<p>Erfasst werden etablierte Bestände mit Altbäumen und Jungpflanzen. Die Kartierung liefert damit Hinweise auf dauerhaftes Überleben und erfolgreiche Fortpflanzung unter natürlichen Konkurrenzbedingungen.</p>']],questions:[q('Datenvergleich','Vergleichen Sie mit Material 1 die Wuchsleistung der Kiefer allein und mit Buche. Gehen Sie auf 15 %, 60 % und 90 % Bodenfeuchte ein.','Bei 15 % beträgt die Leistung in beiden Ansätzen 3, bei 90 % jeweils 4. Bei 60 % wächst die Kiefer allein mit dem Wert 10, mit Buche nur mit 1. Der Rückgang ist im mittleren Feuchtebereich deutlich, an den beiden Randstufen fehlt er.','II'),q('Konkurrenz erklären','Erklären Sie die unterschiedliche Wirkung der Mischkultur auf beide Arten bei 60 % Bodenfeuchte. Beziehen Sie die Daten beider Arten ein.','Kiefer und Buche nutzen begrenzte Ressourcen gemeinsam; es liegt interspezifische Konkurrenz vor. Die Kiefer fällt von 10 auf 1, die Buche nur von 10 auf 9. Dies spricht für eine stärkere Konkurrenzwirkung auf die Kiefer und eine höhere Konkurrenzstärke der Buche unter diesen Bedingungen. Welche einzelne Ressource entscheidend ist, belegen die Daten nicht.','II'),q('Vorkommen deuten','Erklären Sie mit beiden Materialien, weshalb die Kiefer im Modellwald an den Randstandorten häufiger ist als bei 60 % Bodenfeuchte.','Allein wächst die Kiefer bei 60 % am stärksten. Dort wird ihre Leistung durch Buche aber stark vermindert; die Kartierung zeigt eine sehr häufige Buche und seltene Kiefer. Bei 15 und 90 % fehlt die Buche, sodass die Kiefer trotz geringerer Wuchsleistung ohne diesen Konkurrenten häufiger vorkommen kann. Häufigkeit ist somit kein direkter Indikator des physiologischen Optimums.','II'),q('Aussagekraft beurteilen','Beurteilen Sie die Aussage „Die Wachstumstabelle bestimmt exakt die ökologische Potenz der Kiefer“. Berücksichtigen Sie Material 2.','Die Aussage geht zu weit. Ökologische Potenz umfasst dauerhaftes Überleben und Fortpflanzung unter Konkurrenz. Die Tabelle misst nur Wuchsleistung während des Versuchs und nur bei sechs Feuchtestufen. Die langjährige Kartierung mit Jungpflanzen ergänzt wichtige Hinweise, liefert aber ebenfalls keine exakten Grenzwerte für alle Feuchtestufen und Umweltbedingungen.','III')]},
{id:'garten',topic:'nische',title:'Zwei Meisen in einem Garten',desc:'Nischenprofile vergleichen und Folgen eines Gartenumbaus abschätzen.',source:'Neu formuliertes Training nach AB 4 und dem Meisen-Lernprogramm; Nutzungsmuster didaktisch zusammengefasst.',materials:[['Material 1 · Beobachtungen im Garten',table(['Merkmal','Kohlmeise','Blaumeise'],[['Körperbau','Größer, schwerer','Kleiner, leichter'],['Nahrungssuche','Häufig kräftige innere Äste und Boden','Häufig feine äußere Zweige und Blätter'],['Nahrung','Insekten, auch größere Larven; im Winter Samen','Häufig kleine Insekten und Spinnen; auch Samen'],['Zugang zum Nistkasten','32-mm-Öffnung geeignet','26–28-mm-Öffnung geeignet; auch größere Öffnungen nutzbar']])+'<p>Die Angaben beschreiben typische Schwerpunkte. Beide Arten wurden an derselben Futterstelle beobachtet. Die verfügbaren Nistplätze sind begrenzt.</p>'],['Material 2 · Geplanter Umbau','<p>Ein großer Teil der feinen äußeren Zweige soll entfernt werden. Alle Nistkästen sollen künftig 32-mm-Öffnungen besitzen. Zusätzlich sollen in einem anderen Gartenbereich neue Sträucher gepflanzt werden. Über deren spätere Nutzung liegen noch keine Beobachtungen vor.</p>']],questions:[q('Begriffe anwenden','Erläutern Sie an Material 1 den Unterschied zwischen gemeinsamem Lebensraum und ökologischer Nische.','Der Garten ist der gemeinsame Lebensraum. Die Nische umfasst die jeweiligen Umweltansprüche und Beziehungen. Trotz desselben Ortes unterscheiden sich typische Nahrungssuchbereiche, Beutegrößen und der Zugang zu kleinen Nistöffnungen. Beide Arten können daher unterschiedliche Nischen besitzen.','II'),q('Koexistenz erklären','Erklären Sie mit drei Angaben aus Material 1, wodurch Konkurrenz verringert werden kann.','Der kleinere Körper der Blaumeise ermöglicht die Nutzung feiner äußerer Zweige, während die Kohlmeise häufiger kräftige Äste nutzt. Unterschiedliche Beutegrößen können die Überlappung bei Nahrung verringern. Kleine Nistöffnungen sind nur für die Blaumeise zugänglich. Diese Nischendifferenzierung kann Konkurrenz reduzieren; vollständig aufgehoben ist sie wegen gemeinsamer Nahrung und teilweise gemeinsamer Nistplätze nicht.','II'),q('Folgen ableiten','Leiten Sie aus den Materialien zwei mögliche Folgen des Umbaus für die Konkurrenz ab.','Der Verlust feiner Zweige kann die typische Nahrungssuche der Blaumeise einschränken und die Überlappung in verbleibenden Bereichen erhöhen. Nur noch große Nistöffnungen machen alle angebotenen Kästen für beide Arten zugänglich; bei begrenzten Plätzen kann die Konkurrenz zunehmen. Neue Sträucher könnten Ausweichmöglichkeiten schaffen, deren Nutzung ist aber noch offen.','II'),q('Prognose beurteilen','Beurteilen Sie die Behauptung „Nach dem Umbau verschwindet die Blaumeise sicher“. Begründen Sie anhand der Nischenprofile, welche Veränderungen sie benachteiligen und welche Ausweichmöglichkeiten bestehen könnten.','Die Behauptung ist nicht ausreichend belegt. Das Material stützt mögliche Konkurrenzzunahme, beweist aber keine vollständige Verdrängung. Ausweichressourcen, Nahrungsangebot und Nutzung der neuen Sträucher sind unbekannt. Die kleineren Körpermaße der Blaumeise ermöglichen weiterhin andere Nutzungsschwerpunkte als bei der Kohlmeise, sofern geeignete feine Zweige und Nahrung erhalten bleiben oder in den neuen Sträuchern entstehen. Mehr Überlappung kann Konkurrenz verstärken, bedeutet aber nicht automatisch vollständigen Konkurrenzausschluss.','III')]},
{id:'bienen',topic:'standort',title:'Eine Fläche für die Bienen-AG',desc:'Standortdaten und Pflanzenprofile auswerten, eine Maßnahme abwägen.',source:'Standortangaben und Pflanzenprofile aus AB 5, gekürzt; Aufgaben für den Lernraum neu formuliert.',materials:[['Material 1 · Zwei Schulflächen',siteTable],['Material 2 · Pflanzenprofile',plants],['Material 3 · Rahmen der Entscheidung','<p>Die Bienen-AG möchte über mehrere Monate Blüten anbieten. Die Mitte der Rasenfläche muss als Pausenfläche erhalten bleiben; ein Randstreifen kann anders gepflegt werden. Die Laubbäume bleiben erhalten. Es gibt keine zusätzlichen Messungen zur Nährstoffversorgung. Die Pflege muss mit dem vorhandenen Schulbetrieb vereinbar sein.</p>']],questions:[q('Standorte vergleichen','Vergleichen Sie die Standorte A und B anhand von Licht, Bodenfeuchte und Nutzung in Material 1.','A ist am Messzeitpunkt mit 42.000 Lux heller als B mit 3.500 Lux; B wird im Frühjahr vor Laubaustrieb heller als im belaubten Sommer. A ist mäßig trocken, B mäßig feucht. A wird regelmäßig gemäht und als Pausenfläche betreten, B selten betreten und nicht regelmäßig gemäht.','I–II'),q('Pflanzenauswahl begründen','Begründen Sie mit Material 1 und 2 die Eignung von Weißklee für A und Lungenkraut für B. Nennen Sie je eine Unsicherheit oder notwendige Bedingung.','Weißklee passt zu hellen Standorten und verträgt Mahd grundsätzlich. Auf A muss aber ausreichend Feuchte vorhanden sein; Blütenstände dürfen nicht ständig abgeschnitten werden. Lungenkraut passt zu dem halbschattigen bis schattigen, humusreichen und mäßig feuchten Standort B und kann vor Laubaustrieb blühen. Die Nährstoffversorgung ist noch zu prüfen; längere Trockenphasen könnten ungünstig sein.','II'),q('Überleben und Blütenangebot','Erklären Sie anhand von Weißklee und Wurmfarn, warum eine überlebende Pflanze nicht automatisch Nahrung für Bienen bereitstellt.','Weißklee kann mit seinen kriechenden Trieben Mahd überstehen, während Blütenstände abgeschnitten werden; ohne Blüten liefert er dann keinen Nektar oder Pollen. Wurmfarn kann unter den Bäumen gut wachsen, bildet als Sporenpflanze aber überhaupt keine Blüten, keinen Nektar und keinen Pollen.','II'),q('Maßnahme beurteilen','Entwickeln und beurteilen Sie anhand der Materialien einen Vorschlag. Berücksichtigen Sie Standorteignung, Blütezeit, Pflege und Nutzung. Nennen Sie einen Zielkonflikt und eine offene Frage.','Ein möglicher Vorschlag: Einen sonnigen Randstreifen mit vorhandenen Gänseblümchen, Weißklee und Kleiner Braunelle abschnittsweise später mähen, sodass Blüten erhalten bleiben. Die Mitte bleibt kurz und nutzbar. Lungenkraut kann unter Bäumen ein Frühjahrsangebot ergänzen. Weißklee und Braunelle tragen vor allem von Mai bzw. Juni bis September bei; die Profile garantieren keine lückenlose tatsächliche Blüte. Zielkonflikt: längere Blüte versus Pflegeaufwand und nutzbare Fläche; bei vollständigem Mahdverzicht können hohe Gräser konkurrenzstark werden. Zu prüfen sind Feuchte, Nährstoffe und tatsächlicher Blütenbesuch. Andere materialgestützt begründete Vorschläge sind möglich.','III')]},
{id:'partner',topic:'parasitismus',title:'Zusammenleben: Nutzen oder Schaden?',desc:'Symbiose und Parasitismus vergleichen und die Aussagekraft von Befunden prüfen.',source:'AB 6 und 7 sowie zugehörige DOCX-Materialien; dortige Fachquellen: Australian Museum (McGrouther, 2020), Brusca & Gilligan (1983), University of Texas Biodiversity Center (2021).',materials:[['Material 1 · Grundel und Knallkrebs','<p>Der Knallkrebs baut und unterhält eine Höhle, die beide Tiere als Rückzugsort nutzen. Er sieht schlecht. Die Grundel beobachtet mit ihren gut entwickelten Augen die Umgebung. Der Krebs hält beim Verlassen der Höhle über einen Fühler Kontakt zum Fisch. Bei Gefahr führt die Grundel zitternde Bewegungen aus, die der Krebs über den Kontakt wahrnehmen kann.</p>'],['Material 2 · Assel und Schnapperfisch','<p>Die Assel <i>Cymothoa exigua</i> heftet sich mit hakenförmigen Beinenden im Maul an. Nach der gängigen Erklärung wird die Blutversorgung der Zunge geschädigt. Das Gewebe verkümmert; die Assel bleibt am Zungenstumpf und Mundboden befestigt. Als Nahrung werden Blut und Schleim beschrieben; die genaue Ernährung im erwachsenen Stadium ist nicht abschließend geklärt.</p><p>Bei zwei untersuchten befallenen Fischen fehlten mehr als 90 % der Zunge. Beide hatten dennoch Nahrung aufgenommen. Die Forschenden vermuteten eine teilweise mechanische Ersatzfunktion der Assel. Ein Vorteil befallener gegenüber gesunden Fischen wurde damit nicht nachgewiesen.</p>']],questions:[q('Nutzen erklären','Erklären Sie für beide Partner in Material 1 jeweils einen Nutzen und ordnen Sie die Beziehung begründet ein.','Die Grundel nutzt die vom Krebs gebaute und unterhaltene Höhle als Schutzraum. Der schlecht sehende Krebs erhält Warninformationen über den Fühlerkontakt zur gut sehenden Grundel. Beide profitieren; dies ist Symbiose im engeren Sinn (+/+).','II'),q('Wirkungskette darstellen','Stellen Sie mit Material 2 die Erklärung des Zungenverlusts als beschriftete Pfeilkette dar.','Anheften der Assel → Schädigung der Blutversorgung → verringerte Sauerstoff- und Nährstoffversorgung des Zungengewebes → Verkümmern der Zunge. Die Assel bleibt am Zungenstumpf und Mundboden befestigt. Die Kette gibt die gängige Erklärung wieder.','II'),q('Befund und Deutung unterscheiden','Unterscheiden Sie in Material 2 einen beobachteten Befund, eine daraus abgeleitete Vermutung und eine offene Frage.','Befund: Zwei befallene Fische hatten trotz Verlusts von mehr als 90 % der Zunge Nahrung aufgenommen. Vermutung: Die Assel übernimmt einen Teil der mechanischen Funktion beim Festhalten von Nahrung. Offen: die genaue Ernährung der erwachsenen Assel. Die Ersatzfunktion darf nicht als unmittelbar beobachteter Gesamtnutzen formuliert werden.','II'),q('Einordnung beurteilen','Beurteilen Sie die Aussage „Die Assel ersetzt die Zunge, also liegt wie bei Grundel und Knallkrebs Symbiose vor“. Verwenden Sie eine geeignete Vergleichssituation.','Die Aussage ist nicht tragfähig. Eine mögliche Ersatzfunktion belegt keinen Vorteil gegenüber einem gesunden Fisch ohne Assel. Der Verlust des Zungengewebes ist ein Schaden. Die Assel profitiert vom Wirt als Lebensraum und Nahrungsquelle, während dieser geschädigt wird: Parasitismus (+/−). Bei Grundel und Knallkrebs ist dagegen für beide ein Nutzen begründet. Dass der befallene Fisch weiter frisst oder lebt, macht die Beziehung nicht zur Symbiose.','III')]}
];

